import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'  import '../widgets/loading_widget.dart'  import '../widgets/empty_state.dart'    class TasksScreen extends ConsumerStatefulWidget {    const TasksScreen({super.key})      @override    ConsumerState<TasksScreen> createState() => _TasksScreenState()  }    class _TasksScreenState extends ConsumerState<TasksScreen> {    List<dynamic> _tasks = []    bool _isLoading = true    String _filterStatus = ''      @override    void initState() {      super.initState()      _loadTasks()    }      Future<void> _loadTasks() async {      try {        final tasks = await ApiClient().getTasks()        if (mounted) setState(() { _tasks = tasks; _isLoading = false })      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      Future<void> _completeTask(int taskId) async {      try {        await ApiClient().completeTask(taskId)        _loadTasks()        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(content: Text('Задача выполнена!')),          )        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка: $e')),          )        }      }    }      String _getPriorityLabel(String? priority) {      final labels = {'low': 'Низкий', 'medium': 'Средний', 'high': 'Высокий', 'urgent': 'Срочный'}      return labels[priority] ?? 'Средний'    }      Color _getPriorityColor(String? priority) {      final colors = {'low': Colors.grey, 'medium': Colors.blue, 'high': Colors.orange, 'urgent': Colors.red}      return colors[priority] ?? Colors.blue    }      String _getStatusLabel(String? status) {      final labels = {'pending': 'В ожидании', 'in_progress': 'В работе', 'completed': 'Выполнена', 'cancelled': 'Отменена'}      return labels[status] ?? status    }      @override    Widget build(BuildContext context) {      final filtered = _filterStatus.isEmpty          ? _tasks          : _tasks.where((t) => t['status'] == _filterStatus).toList()        return Scaffold(        appBar: AppBar(          title: const Text('Задачи'),          actions: [            IconButton(              icon: const Icon(Icons.add),              onPressed: () {},            ),          ],        ),        body: _isLoading            ? const LoadingWidget()            : Column(                children: [                  // Filter chips                  Container(                    height: 50,                    padding: const EdgeInsets.symmetric(horizontal: 16),                    child: ListView(                      scrollDirection: Axis.horizontal,                      children: [                        _FilterChip(                          label: 'Все',                          isSelected: _filterStatus.isEmpty,                          onTap: () => setState(() => _filterStatus = ''),                        ),                        _FilterChip(                          label: 'В ожидании',                          isSelected: _filterStatus == 'pending',                          onTap: () => setState(() => _filterStatus = 'pending'),                        ),                        _FilterChip(                          label: 'В работе',                          isSelected: _filterStatus == 'in_progress',                          onTap: () => setState(() => _filterStatus = 'in_progress'),                        ),                        _FilterChip(                          label: 'Выполнены',                          isSelected: _filterStatus == 'completed',                          onTap: () => setState(() => _filterStatus = 'completed'),                        ),                      ],                    ),                  ),                    // Stats                  Container(                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),                    child: Row(                      children: [                        _StatItem(                          label: 'Всего',                          value: '${_tasks.length}',                          color: Colors.blue,                        ),                        _StatItem(                          label: 'Выполнено',                          value: '${_tasks.where((t) => t['status'] == 'completed').length}',                          color: Colors.green,                        ),                        _StatItem(                          label: 'Просрочено',                          value: '${_tasks.where((t) => t['status'] == 'pending' && t['due_date'] != null && DateTime.parse(t['due_date']).isBefore(DateTime.now())).length}',                          color: Colors.red,                        ),                      ],                    ),                  ),                    // List                  Expanded(                    child: filtered.isEmpty                        ? const EmptyState(                            icon: Icons.task_alt,                            title: 'Нет задач',                            subtitle: 'Создайте первую задачу',                          )                        : RefreshIndicator(                            onRefresh: _loadTasks,                            child: ListView.builder(                              padding: const EdgeInsets.all(16),                              itemCount: filtered.length,                              itemBuilder: (context, index) {                                final task = filtered[index]                                final isOverdue = task['due_date'] != null &&                                    task['status'] != 'completed' &&                                    DateTime.parse(task['due_date']).isBefore(DateTime.now())                                  return Card(                                  margin: const EdgeInsets.only(bottom: 12),                                  child: ListTile(                                    leading: Checkbox(                                      value: task['status'] == 'completed',                                      onChanged: task['status'] == 'completed'                                          ? null                                          : (_) => _completeTask(task['id']),                                    ),                                    title: Text(                                      task['title'] ?? 'Без названия',                                      style: TextStyle(                                        fontWeight: FontWeight.w600,                                        decoration: task['status'] == 'completed'                                            ? TextDecoration.lineThrough                                            : null,                                        color: task['status'] == 'completed' ? Colors.grey : null,                                      ),                                    ),                                    subtitle: Column(                                      crossAxisAlignment: CrossAxisAlignment.start,                                      children: [                                        if (task['description'] != null)                                          Text(                                            task['description'],                                            style: TextStyle(fontSize: 12, color: Colors.grey[600]),                                            maxLines: 2,                                            overflow: TextOverflow.ellipsis,                                          ),                                        const SizedBox(height: 4),                                        Row(                                          children: [                                            Container(                                              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),                                              decoration: BoxDecoration(                                                color: _getPriorityColor(task['priority']).withOpacity(0.1),                                                borderRadius: BorderRadius.circular(6),                                              ),                                              child: Text(                                                _getPriorityLabel(task['priority']),                                                style: TextStyle(                                                  fontSize: 10,                                                  color: _getPriorityColor(task['priority']),                                                ),                                              ),                                            ),                                            const SizedBox(width: 8),                                            if (task['due_date'] != null)                                              Text(                                                'До: ${DateTime.parse(task['due_date']).day.toString().padLeft(2, '0')}.${DateTime.parse(task['due_date']).month.toString().padLeft(2, '0')}',                                                style: TextStyle(                                                  fontSize: 11,                                                  color: isOverdue ? Colors.red : Colors.grey[600],                                                ),                                              ),                                          ],                                        ),                                      ],                                    ),                                    trailing: isOverdue                                        ? const Icon(Icons.warning_amber, color: Colors.red, size: 20)                                        : null,                                  ),                                )                              },                            ),                          ),                  ),                ],              ),      )    }  }    class _FilterChip extends StatelessWidget {    final String label    final bool isSelected    final VoidCallback onTap      const _FilterChip({required this.label, required this.isSelected, required this.onTap})      @override    Widget build(BuildContext context) {      return Padding(        padding: const EdgeInsets.only(right: 8),        child: ChoiceChip(          label: Text(label),          selected: isSelected,          selectedColor: Theme.of(context).colorScheme.primary,          backgroundColor: Colors.grey[200],          onSelected: (_) => onTap(),        ),      )    }  }    class _StatItem extends StatelessWidget {    final String label    final String value    final Color color      const _StatItem({required this.label, required this.value, required this.color})      @override    Widget build(BuildContext context) {      return Expanded(        child: Container(          padding: const EdgeInsets.symmetric(vertical: 12),          margin: const EdgeInsets.symmetric(horizontal: 4),          decoration: BoxDecoration(            color: color.withOpacity(0.1),            borderRadius: BorderRadius.circular(12),          ),          child: Column(            children: [              Text(value, style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: color)),              const SizedBox(height: 4),              Text(label, style: TextStyle(fontSize: 11, color: Colors.grey[600])),            ],          ),        ),      )    }  }